import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "पैरों में जलन? सुन्नपन? या चींटी चलने जैसा महसूस होना? हाथ में झुनझुनी? ऐसे में डॉक्टर नसों की जांच, यानी एन सी वी, लिख सकते हैं. आखिर तक देखिए.",
 "हमारी नसें बिजली के तार जैसी हैं. इनके ऊपर एक परत होती है, जिसे मायलिन कहते हैं, जैसे तार के ऊपर प्लास्टिक. इसी परत से संदेश तेज़ी से चलता है.",
 "एन सी वी, यानी नर्व कंडक्शन वेलोसिटी, मापता है कि नस में संदेश कितनी तेज़ी से, और कितनी ताकत से चलता है. नस को दो जगह हल्का झटका देकर, दूरी और समय से गति निकाली जाती है.",
 "अगर नस का अंदर का तार खराब हो, तो संदेश कमज़ोर हो जाता है. अगर ऊपर की परत खराब हो, तो संदेश धीमा हो जाता है. और अगर कहीं नस दबी हो, तो संदेश वहां रुक सकता है.",
 "यह किन बीमारियों में मदद करता है? डायबिटीज़ से नसों की कमज़ोरी, कार्पल टनल सिंड्रोम, चेहरे का लकवा यानी बेल्स पाल्सी, गिलियन बारे सिंड्रोम, चोट से नस को नुकसान, और रीढ़ की डिस्क से नस दबना.",
 "टेस्ट कैसे होता है? त्वचा पर स्टिकर जैसे इलेक्ट्रोड लगते हैं, और नस पर हल्का बिजली का झटका दिया जाता है. यह कुछ पल के लिए झटके जैसा लगता है, पर बाद में दर्द नहीं रहता. एन सी वी में आमतौर पर सुई नहीं लगती. साथ में ई एम जी हो, तो सुई लगती है.",
 "तैयारी कैसे करें? उस दिन त्वचा पर लोशन, क्रीम, तेल, सनस्क्रीन या परफ्यूम न लगाएं. ढीले कपड़े पहनें. पेसमेकर लगा हो, तो पहले बताएं. और ठंड में हाथ पैर गर्म रखें, क्योंकि ठंडी नस में संदेश धीमा चलता है, और रिपोर्ट गलत आ सकती है.",
 "टेस्ट में पंद्रह मिनट से एक घंटे से ज़्यादा भी लग सकता है. यह इस पर निर्भर है कि कितनी नसें जांची जा रही हैं. छोटे बच्चों में नस की गति कम होती है, इसलिए रिपोर्ट उम्र के हिसाब से देखी जाती है.",
 "एक ज़रूरी बात. नॉर्मल एन सी वी का मतलब हमेशा यह नहीं, कि नस में कोई नुकसान नहीं है. सामान्य सीमा हर लैब में थोड़ी अलग होती है. इसलिए रिपोर्ट को डॉक्टर आपके लक्षणों और जांच के साथ समझते हैं.",
 close_voice("क्या आपके पैरों में कभी जलन या सुन्नपन होता है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/ncvr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/ncv_{i}.wav"],check=True); f=f"/tmp/ncv_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/ncv_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
